import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('schema validation', () => {
    it('rejects input missing required property before calling executor', async () => {
      const registry = new ToolRegistry();
      let executorCalls = 0;

      registry.register(
        {
          name: 'test_tool',
          description: 'Test tool',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'string'}},
            required: ['location'],
          },
        },
        async () => {
          executorCalls += 1;
          return 'result';
        }
      );

      const response = await registry.execute('test_tool', {});

      expect(response.result).toContain('location');
      expect(response.result).toMatch(/required/i);
      expect(executorCalls).toBe(0);
    });
  });
});

