describe('ToolRegistry', () => {
  describe('schema compilation', () => {
    it('compiles static tool schema once across multiple execute calls', async () => {
      const registry = new ToolRegistry();
      let compileCount = 0;
      const originalCompile = Ajv.prototype.compile;

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      Ajv.prototype.compile = function (this: any, schema: any) {
        compileCount += 1;
        return originalCompile.call(this, schema);
      };

      try {
        registry.register(
          {
            name: 'test_tool',
            description: 'Test tool',
            inputSchema: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
          async () => 'result'
        );

        for (let i = 0; i < 10; i++) {
          await registry.execute('test_tool', {location: 'Paris'});
        }

        expect(compileCount).toEqual(1);
      } finally {
        Ajv.prototype.compile = originalCompile;
      }
    });
  });
});

