      throw new Error(`Unknown tool: ${name}`);
    }

    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.getOrCompileValidator(tool, definition);

    if (!validator(input)) {
      return {result: this.formatValidationErrors(validator)};
    }

