import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('schema compilation', () => {
    it('compiles static tool schema once across multiple execute calls', async () => {
      const registry = new ToolRegistry();
      const testSchema = {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      };

      registry.register(
        {
          name: 'test_tool',
          description: 'Test tool',
          inputSchema: testSchema,
        },
        async () => 'result'
      );

      for (let i = 0; i < 10; i++) {
        await registry.execute('test_tool', {location: 'Paris'});
      }

      // Test passes if no errors thrown - schema compilation is internal
      expect(true).toEqual(true);
    });
  });
});

